func resetViper(t *testing.T) {
	t.Helper()
	viper.Reset()
	t.Cleanup(viper.Reset)
}

func TestResolveJWTSecret_ViperValueWins(t *testing.T) {
	resetViper(t)
	viper.Set("auth.jwt_secret", "configured-secret")

	store, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()
	// A different stored value must be ignored when config/env is set.
	if err := store.SetSetting(context.Background(), jwtSecretSettingKey, "stored-secret"); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}

	got, err := resolveJWTSecret(context.Background(), store, nil)
	if err != nil {
		t.Fatalf("resolveJWTSecret: %v", err)
	}
	if got != "configured-secret" {
		t.Errorf("got %q, want configured value", got)
	}
}

func TestResolveJWTSecret_EnvAliases(t *testing.T) {
	for _, name := range []string{"FAUCET_AUTH_JWT_SECRET", "FAUCET_JWT_SECRET"} {
		t.Run(name, func(t *testing.T) {
			resetViper(t)
			t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
			t.Setenv("FAUCET_JWT_SECRET", "")
			t.Setenv(name, "from-"+name)
			initConfig()

			store, err := config.NewStore("")
			if err != nil {
				t.Fatalf("NewStore: %v", err)
			}
			defer store.Close()

			got, err := resolveJWTSecret(context.Background(), store, nil)
			if err != nil {
				t.Fatalf("resolveJWTSecret: %v", err)
			}
			if got != "from-"+name {
				t.Errorf("got %q, want value from %s", got, name)
			}
		})
	}
}

func TestResolveJWTSecret_GeneratedAndPersisted(t *testing.T) {
	resetViper(t)
	t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
	t.Setenv("FAUCET_JWT_SECRET", "")

	store, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	var buf bytes.Buffer
	logger := slog.New(slog.NewTextHandler(&buf, nil))

	first, err := resolveJWTSecret(context.Background(), store, logger)
	if err != nil {
		t.Fatalf("first resolveJWTSecret: %v", err)
	}
	if first == "" || first == "faucet-dev-secret-change-me" {
		t.Fatalf("expected a generated secret, got %q", first)
	}
	raw, err := hex.DecodeString(first)
	if err != nil || len(raw) != jwtSecretBytes {
		t.Errorf("secret should be %d hex-encoded random bytes, got %q (err=%v)", jwtSecretBytes, first, err)
	}
	if !strings.Contains(buf.String(), "generated a new JWT signing secret") {
		t.Errorf("expected INFO log about generation, got %q", buf.String())
	}

	stored, err := store.GetSetting(context.Background(), jwtSecretSettingKey)
	if err != nil {
		t.Fatalf("GetSetting: %v", err)
	}
	if stored != first {
		t.Errorf("persisted secret %q != returned %q", stored, first)
	}

	buf.Reset()
	second, err := resolveJWTSecret(context.Background(), store, logger)
	if err != nil {
		t.Fatalf("second resolveJWTSecret: %v", err)
	}
	if second != first {
		t.Errorf("secret not stable across calls: %q vs %q", first, second)
	}
	if strings.Contains(buf.String(), "generated") {
		t.Errorf("second call should not generate again, got log %q", buf.String())
	}

	// Two independent stores generate different secrets.
	other, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer other.Close()
	third, err := resolveJWTSecret(context.Background(), other, nil)
	if err != nil {
		t.Fatalf("resolveJWTSecret on other store: %v", err)
	}
	if third == first {
		t.Error("two stores produced the same generated secret")
	}
}

func TestResolveJWTSecret_NilStore(t *testing.T) {
	resetViper(t)
	t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
	t.Setenv("FAUCET_JWT_SECRET", "")
	if _, err := resolveJWTSecret(context.Background(), nil, nil); err == nil {
		t.Error("expected error with nil store and no configured secret")
	}
}

package snowflake

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeTempPEM writes a PEM-encoded private key to a temp file and returns its path.
func writeTempPEM(t *testing.T, blockType string, derBytes []byte) string {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "key.pem")
	buf := pem.EncodeToMemory(&pem.Block{Type: blockType, Bytes: derBytes})
	if err := os.WriteFile(path, buf, 0600); err != nil {
		t.Fatalf("write temp PEM: %v", err)
	}
	return path
}

// generateTestKey creates a 2048-bit RSA key for testing.
func generateTestKey(t *testing.T) *rsa.PrivateKey {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatalf("generate RSA key: %v", err)
	}
	return key
}

func TestLoadPrivateKey_PKCS1(t *testing.T) {
	key := generateTestKey(t)
	der := x509.MarshalPKCS1PrivateKey(key)
	path := writeTempPEM(t, "RSA PRIVATE KEY", der)

	loaded, err := loadPrivateKey(path)
	if err != nil {
		t.Fatalf("loadPrivateKey PKCS1: %v", err)
	}
	if loaded.N.Cmp(key.N) != 0 {
		t.Error("loaded key modulus does not match original")
	}
}

func TestLoadPrivateKey_PKCS8(t *testing.T) {
	key := generateTestKey(t)
	der, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		t.Fatalf("marshal PKCS8: %v", err)
	}
	path := writeTempPEM(t, "PRIVATE KEY", der)

	loaded, err := loadPrivateKey(path)
	if err != nil {
		t.Fatalf("loadPrivateKey PKCS8: %v", err)
	}
	if loaded.N.Cmp(key.N) != 0 {
		t.Error("loaded key modulus does not match original")
	}
}

func TestLoadPrivateKey_FileNotFound(t *testing.T) {
	_, err := loadPrivateKey("/nonexistent/path/key.pem")
	if err == nil {
		t.Fatal("expected error for missing file")
	}
	if !strings.Contains(err.Error(), "read private key file") {
		t.Errorf("unexpected error: %v", err)
	}
}

func TestLoadPrivateKey_InvalidPEM(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "bad.pem")
	os.WriteFile(path, []byte("not a pem file"), 0600)

	_, err := loadPrivateKey(path)
	if err == nil {
		t.Fatal("expected error for invalid PEM")
	}
	if !strings.Contains(err.Error(), "no PEM block") {
		t.Errorf("unexpected error: %v", err)
	}
}

func TestLoadPrivateKey_UnsupportedBlockType(t *testing.T) {
	path := writeTempPEM(t, "EC PRIVATE KEY", []byte("fake"))

	_, err := loadPrivateKey(path)
	if err == nil {
		t.Fatal("expected error for unsupported block type")
	}
	if !strings.Contains(err.Error(), "unsupported PEM block type") {
		t.Errorf("unexpected error: %v", err)
	}
}

func TestBuildJWTDSN(t *testing.T) {
	key := generateTestKey(t)
	der, _ := x509.MarshalPKCS8PrivateKey(key)
	keyPath := writeTempPEM(t, "PRIVATE KEY", der)

	// Use a valid Snowflake DSN format: user@account/db/schema
	dsn := "testuser@testaccount/testdb/PUBLIC?warehouse=WH"

	newDSN, err := buildJWTDSN(dsn, keyPath)
	if err != nil {
		t.Fatalf("buildJWTDSN: %v", err)
	}

	// The rebuilt DSN should contain the authenticator=snowflake_jwt param
	lowerDSN := strings.ToLower(newDSN)
	if !strings.Contains(lowerDSN, "authenticator=snowflake_jwt") {
		t.Errorf("DSN missing authenticator param: %s", newDSN)
	}

	// Should still contain the original user and account info
	if !strings.Contains(newDSN, "testuser") {
		t.Errorf("DSN missing user: %s", newDSN)
	}
}

func TestBuildJWTDSN_InvalidDSN(t *testing.T) {
	key := generateTestKey(t)
	der, _ := x509.MarshalPKCS8PrivateKey(key)
	keyPath := writeTempPEM(t, "PRIVATE KEY", der)

	_, err := buildJWTDSN(":::invalid", keyPath)
	if err == nil {
		t.Fatal("expected error for invalid DSN")
	}
}

func TestBuildJWTDSN_BadKeyFile(t *testing.T) {
	_, err := buildJWTDSN("testuser@testaccount/testdb/PUBLIC", "/nonexistent/key.pem")
	if err == nil {
		t.Fatal("expected error for missing key file")
	}
}

