func TestGenerateServiceSpec_CreateSchemaRequiredFields(t *testing.T) {
	schema := testSchema()
	doc := GenerateServiceSpec("mydb", "My Database", "postgres", "http://localhost:8080", schema)

	createSchema := doc.Components.Schemas["Mydb_UsersCreate"]
	if createSchema == nil {
