func TestListResponseJSON(t *testing.T) {
	total := int64(100)
	lr := ListResponse{
		Resource: []map[string]interface{}{
			{"id": float64(1), "name": "Alice"},
			{"id": float64(2), "name": "Bob"},
		},
		Meta: &ResponseMeta{
			Count:  2,
			Total:  &total,
			Limit:  10,
			Offset: 0,
			TookMs: 1.5,
		},
	}

	b, err := json.Marshal(lr)
	if err != nil {
